import { Heatmap } from '@absoluteui/components/heatmap';

const host = document.createElement('div');
document.body.append(host);
Heatmap.create(host, {
  label: 'Support tickets by weekday and hour',
  columns: ['9:00', '12:00', '15:00', '18:00'],
  rows: ['Mon', 'Tue', 'Wed'],
  values: [
    [4, 12, 9, 3],
    [6, 15, null, 2],
    [5, 11, 8, 4],
  ],
  colorScale: { color: 3, steps: 4 },
  xAxis: { label: 'Hour' },
  yAxis: { label: 'Weekday' },
  height: 240,
});

import { Heatmap } from '@absoluteui/components/heatmap';

const host = document.querySelector<HTMLElement>('#change');
if (host) {
  const chart = Heatmap.create(host, {
    label: 'Change from last year',
    columns: ['Q1', 'Q2', 'Q3', 'Q4'],
    rows: ['North', 'South', 'East'],
    values: [
      [0.12, 0.05, -0.03, 0.08],
      [-0.1, -0.04, 0.02, 0.01],
      [0.03, 0.09, 0.15, -0.06],
    ],
    colorScale: { type: 'diverging', midpoint: 0, negative: 2, positive: 1, steps: 3 },
    valueFormat: { style: 'percent', maximumFractionDigits: 0 },
    dataTable: 'visible',
  });
  chart.update({ cellLabels: 'none' });
}
